2	 * Feature Reviewer Daemon (T4).
3	 *
4	 * Poll step that runs every FEATURE_REVIEW_INTERVAL cycles. For each
5	 * in_handoff feature it detects drift (new commits on the base branch since
6	 * the feature started) and routes to one of three outcomes:
7	 *
8	 *   1. No new commits → skip.
9	 *   2. New commits, no file overlap → auto-rebase feature branch onto base;
10	 *      on rebase conflict fall through to escalation.
11	 *   3. New commits, file overlap → optional Claude API semantic analysis
12	 *      (confidence ≥ threshold → treat as no-overlap/auto-rebase;
13	 *       confidence < threshold → feature-level escalation).
14	 *
15	 * Feature-level escalation:
16	 *   - Sets drift_detected: true + drift_reason in status.yaml on the feature branch.
17	 *   - POSTs to SLACK_WEBHOOK_URL if set; skips gracefully if absent.
18	 */
19	
20	import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
21	import { execSync, spawnSync } from "node:child_process";
22	import { join } from "node:path";
23	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
24	import { buildGitEnv } from "../git-env.js";
25	import { curlJson } from "../utils/curl-json.js";
26	import {
27	  featuresRoot,
28	  featureBranchName,
29	  statusYamlAbsPath,
30	  statusYamlRelPath,
31	} from "../paths.js";
32	
33	// ── Types ─────────────────────────────────────────────────────────────────────
34	
35	export interface RunFeatureReviewCycleOpts {
36	  workspaceRoot: string;
37	  baseBranch: string;
38	  mgmtRepoOwner: string;
39	  mgmtRepoName: string;
40	  githubToken: string;
41	  reviewerGithubToken?: string;
42	  gitAuthorEmail: string;
43	  gitAuthorName?: string;
44	  sshKeyPath?: string;
45	  anthropicApiKey?: string;
46	  slackWebhookUrl?: string;
47	  /** Confidence threshold for semantic analysis. Default: 0.80. */
48	  semanticConfidenceThreshold?: number;
49	  emit: (event: Record<string, unknown>) => void;
50	}
51	
52	interface StatusYaml {
53	  feature_status?: string;
54	  feature_branch?: string;
55	  feature_branch_base_sha?: string | null;
56	  handoff_pr_url?: string | null;
57	  impl_feature_prs?: ImplFeaturePr[];
58	  drift_detected?: boolean;
59	  drift_reason?: string | null;
60	  [key: string]: unknown;
61	}
62	
63	interface ImplFeaturePr {
64	  repo: string;
65	  url: string;
66	  status: "open" | "merged";
67	}
68	
69	interface GitHubCompareResult {
70	  ahead_by: number;
71	  files?: GitHubFile[];
72	  [key: string]: unknown;
73	}
74	
75	interface GitHubFile {
76	  filename: string;
77	  status: string;
78	  [key: string]: unknown;
79	}
80	
81	export interface SemanticAnalysisResult {
82	  confidence: number;
83	  hasConflict: boolean;
84	  reasoning: string;
85	}
86	
87	// ── Helpers ───────────────────────────────────────────────────────────────────
88	
89	function listFeatureIds(workspaceRoot: string): string[] {
90	  const docsPath = featuresRoot(workspaceRoot);
91	  if (!existsSync(docsPath)) return [];
92	  try {
93	    return readdirSync(docsPath, { withFileTypes: true })
94	      .filter((e) => e.isDirectory())
95	      .map((e) => e.name);
96	  } catch {
97	    return [];
98	  }
99	}
100	
101	function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
102	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
103	  if (!existsSync(statusPath)) return {};
104	  try {
105	    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
106	  } catch {
107	    return {};
108	  }
109	}
110	
111	/**
112	 * Classify whether new base commits overlap with files changed by the feature.
113	 * Exported for unit testing.
114	 */
115	export function classifyFileOverlap(
116	  newBaseFiles: string[],
117	  featureFiles: string[],
118	): { hasOverlap: boolean; overlappingFiles: string[] } {
119	  const featureFileSet = new Set(featureFiles);
120	  const overlappingFiles = newBaseFiles.filter((f) => featureFileSet.has(f));
121	  return { hasOverlap: overlappingFiles.length > 0, overlappingFiles };
122	}
123	
124	/**
125	 * Call Claude API to semantically classify whether overlapping file changes
126	 * are likely to conflict. Returns a confidence score and conflict verdict.
127	 * Exported for unit testing with a mocked fetch.
128	 */
129	export async function runSemanticAnalysis(
130	  overlappingFiles: string[],
131	  newBaseFileSummary: string,
132	  featureFileSummary: string,
133	  anthropicApiKey: string,
134	): Promise<SemanticAnalysisResult> {
135	  const prompt = [
136	    "You are analyzing whether code changes from two separate sources conflict.",
137	    "",
138	    `Files changed in both new base commits and the in-progress feature: ${overlappingFiles.join(", ")}`,
139	    "",
140	    "New base commit changes (summary):",
141	    newBaseFileSummary.slice(0, 2000),
142	    "",
143	    "In-progress feature changes (summary):",
144	    featureFileSummary.slice(0, 2000),
145	    "",
146	    "Do these changes conflict semantically? Respond ONLY with valid JSON:",
147	    '{"confidence": <0.0-1.0, where 1.0 = certain no conflict>, "has_conflict": <boolean>, "reasoning": "<one sentence>"}',
148	  ].join("\n");
149	
150	  const response = await fetch("https://api.anthropic.com/v1/messages", {
151	    method: "POST",
152	    headers: {
153	      "x-api-key": anthropicApiKey,
154	      "anthropic-version": "2023-06-01",
155	      "content-type": "application/json",
156	    },
157	    body: JSON.stringify({
158	      model: "claude-haiku-4-5-20251001",
159	      max_tokens: 256,
160	      messages: [{ role: "user", content: prompt }],
161	    }),
162	  });
163	
164	  if (!response.ok) {
165	    throw new Error(`Anthropic API error ${response.status}: ${await response.text()}`);
166	  }
167	
168	  const data = (await response.json()) as {
169	    content: Array<{ type: string; text: string }>;
170	  };
171	  const text = data.content.find((c) => c.type === "text")?.text ?? "";
172	
173	  const jsonMatch = /\{[\s\S]*?\}/.exec(text);
174	  if (!jsonMatch) {
175	    throw new Error(`Cannot parse semantic analysis JSON from: ${text}`);
176	  }
177	
178	  const parsed = JSON.parse(jsonMatch[0]) as {
179	    confidence: number;
180	    has_conflict: boolean;
181	    reasoning: string;
182	  };
183	
184	  return {
185	    confidence: parsed.confidence,
186	    hasConflict: parsed.has_conflict,
187	    reasoning: parsed.reasoning,
188	  };
189	}
190	
191	/**
192	 * Attempt to rebase the feature branch onto the base branch.
193	 * Returns success: true and pushes on clean rebase.
194	 * Returns success: false (with conflictDetails) if rebase conflicts or push fails.
195	 */
196	export function tryAutoRebase(
197	  opts: Pick<
198	    RunFeatureReviewCycleOpts,
199	    "workspaceRoot" | "baseBranch" | "gitAuthorEmail" | "gitAuthorName" | "sshKeyPath" | "emit"
200	  >,
201	  featureId: string,
202	): { success: boolean; conflictDetails?: string } {
203	  const {
204	    workspaceRoot,
205	    baseBranch,
206	    gitAuthorEmail,
207	    gitAuthorName = gitAuthorEmail,
208	    sshKeyPath,
209	    emit,
210	  } = opts;
211	  const featureBranch = featureBranchName(featureId);
212	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
213	
214	  try {
215	    execSync("git fetch origin", {
216	      cwd: workspaceRoot,
217	      env,
218	      encoding: "utf-8",
219	      stdio: "pipe",
220	      timeout: 60_000,
221	    });
222	    execSync(`git checkout -B "${featureBranch}" "origin/${featureBranch}"`, {
223	      cwd: workspaceRoot,
224	      env,
225	      encoding: "utf-8",
226	      stdio: "pipe",
227	      timeout: 30_000,
228	    });
229	  } catch (e) {
230	    return { success: false, conflictDetails: `checkout failed: ${String(e)}` };
231	  }
232	
233	  try {
234	    execSync(`git rebase "origin/${baseBranch}"`, {
235	      cwd: workspaceRoot,
236	      env,
237	      encoding: "utf-8",
238	      stdio: "pipe",
239	      timeout: 60_000,
240	    });
241	  } catch (rebaseErr) {
242	    try {
243	      execSync("git rebase --abort", {
244	        cwd: workspaceRoot,
245	        env,
246	        encoding: "utf-8",
247	        stdio: "pipe",
248	        timeout: 30_000,
249	      });
250	    } catch { /* ignore abort errors */ }
251	    return {
252	      success: false,
253	      conflictDetails:
254	        (rebaseErr as { stderr?: string }).stderr?.slice(0, 500) ?? String(rebaseErr),
255	    };
256	  }
257	
258	  const pushResult = spawnSync(
259	    "git",
260	    ["-C", workspaceRoot, "push", "origin", featureBranch, "--force-with-lease"],
261	    { env, encoding: "utf-8" },
262	  );
263	
264	  if (pushResult.status !== 0) {
265	    emit({
266	      type: "feature_review_push_failed",
267	      feature_id: featureId,
268	      details: pushResult.stderr,
269	    });
270	    return { success: false, conflictDetails: pushResult.stderr };
271	  }
272	
273	  return { success: true };
274	}
275	
276	/**
277	 * Write drift_detected + drift_reason to status.yaml, commit + push to the
278	 * feature branch, and post a Slack message if SLACK_WEBHOOK_URL is set.
279	 */
280	async function escalateFeatureDrift(
281	  opts: RunFeatureReviewCycleOpts,
282	  featureId: string,
283	  driftReason: string,
284	): Promise<void> {
285	  const {
286	    workspaceRoot,
287	    gitAuthorEmail,
288	    gitAuthorName = gitAuthorEmail,
289	    sshKeyPath,
290	    slackWebhookUrl,
291	    emit,
292	  } = opts;
293	
294	  const featureBranch = featureBranchName(featureId);
295	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
296	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
297	  const statusRel = statusYamlRelPath(featureId);
298	
299	  try {
300	    execSync("git fetch origin", {
301	      cwd: workspaceRoot,
302	      env,
303	      encoding: "utf-8",
304	      stdio: "pipe",
305	      timeout: 60_000,
306	    });
307	    execSync(`git checkout -B "${featureBranch}" "origin/${featureBranch}"`, {
308	      cwd: workspaceRoot,
309	      env,
310	      encoding: "utf-8",
311	      stdio: "pipe",
312	      timeout: 30_000,
313	    });
314	
315	    const freshStatus = readStatusYaml(workspaceRoot, featureId);
316	    freshStatus.drift_detected = true;
317	    freshStatus.drift_reason = driftReason;
318	    writeFileSync(statusPath, yamlStringify(freshStatus), "utf-8");
319	
320	    execSync(`git add "${statusRel}"`, {
321	      cwd: workspaceRoot,
322	      env,
323	      encoding: "utf-8",
324	      stdio: "pipe",
325	      timeout: 10_000,
326	    });
327	    try {
328	      execSync(
329	        `git commit -m "chore(${featureId}): drift_detected — base branch advanced"`,
330	        { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
331	      );
332	    } catch (e) {
333	      const stderr = (e as { stderr?: string }).stderr ?? String(e);
334	      if (!stderr.includes("nothing to commit")) throw e;
335	    }
336	
337	    const pushResult = spawnSync(
338	      "git",
339	      ["-C", workspaceRoot, "push", "origin", featureBranch],
340	      { env, encoding: "utf-8" },
341	    );
342	    if (pushResult.status !== 0) {
343	      emit({
344	        type: "drift_escalation_push_failed",
345	        feature_id: featureId,
346	        details: pushResult.stderr,
347	      });
348	    }
349	  } catch (e) {
350	    emit({ type: "drift_escalation_failed", feature_id: featureId, details: String(e) });
351	    return;
352	  }
353	
354	  emit({ type: "drift_escalated", feature_id: featureId, drift_reason: driftReason });
355	
356	  if (slackWebhookUrl) {
357	    try {
358	      const resp = await fetch(slackWebhookUrl, {
359	        method: "POST",
360	        headers: { "Content-Type": "application/json" },
361	        body: JSON.stringify({
362	          text: `[Drift Detected] Feature \`${featureId}\` requires human review`,
363	          blocks: [
364	            {
365	              type: "section",
366	              text: {
367	                type: "mrkdwn",
368	                text: `*Base branch has advanced past feature \`${featureId}\`*\n${driftReason}`,
369	              },
370	            },
371	          ],
372	        }),
373	      });
374	      if (!resp.ok) {
375	        emit({
376	          type: "drift_slack_failed",
377	          feature_id: featureId,
378	          status: resp.status,
379	        });
380	      } else {
381	        emit({ type: "drift_slack_sent", feature_id: featureId });
382	      }
383	    } catch (e) {
384	      emit({ type: "drift_slack_failed", feature_id: featureId, details: String(e) });
385	    }
386	  } else {
387	    emit({ type: "drift_slack_skipped", feature_id: featureId, reason: "no_webhook_url" });
388	  }
389	}
390	
391	// ── Main export ───────────────────────────────────────────────────────────────
392	
393	/**
394	 * Run one iteration of the feature reviewer for all in_handoff features in
395	 * a single workspace. Intended to be called from the orchestrator poll loop
396	 * every FEATURE_REVIEW_INTERVAL cycles.
397	 */
398	export async function runFeatureReviewCycle(opts: RunFeatureReviewCycleOpts): Promise<void> {
399	  const {
400	    workspaceRoot,
401	    baseBranch,
402	    mgmtRepoOwner,
403	    mgmtRepoName,
404	    githubToken,
405	    anthropicApiKey,
406	    slackWebhookUrl,
407	    emit,
408	  } = opts;
409	
410	  const CONFIDENCE_THRESHOLD = opts.semanticConfidenceThreshold ?? 0.80;
411	
412	  if (!githubToken) {
413	    emit({ type: "feature_review_skipped", reason: "no_github_token" });
414	    return;
415	  }
416	
417	  const featureIds = listFeatureIds(workspaceRoot);
418	
419	  for (const featureId of featureIds) {
420	    const statusYaml = readStatusYaml(workspaceRoot, featureId);
421	
422	    if (statusYaml.feature_status !== "in_handoff") continue;
423	
424	    if (statusYaml.drift_detected) {
425	      emit({
426	        type: "feature_review_skipped",
427	        feature_id: featureId,
428	        reason: "drift_already_detected",
429	      });
430	      continue;
431	    }
432	
433	    const featureBranchBaseSha = statusYaml.feature_branch_base_sha;
434	    if (!featureBranchBaseSha) {
435	      emit({
436	        type: "feature_review_skipped",
437	        feature_id: featureId,
438	        reason: "no_feature_branch_base_sha",
439	      });
440	      continue;
441	    }
442	
443	    // ── Step 1: Compare feature_branch_base_sha..baseBranch ──────────────────
444	    let compareResult: GitHubCompareResult;
445	    try {
446	      compareResult = curlJson([
447	        "-s",
448	        "-H", `Authorization: token ${githubToken}`,
449	        "-H", "Accept: application/vnd.github+json",
450	        `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/compare/${featureBranchBaseSha}...${baseBranch}`,
451	      ]) as GitHubCompareResult;
452	    } catch (e) {
453	      emit({
454	        type: "feature_review_compare_failed",
455	        feature_id: featureId,
456	        details: String(e),
457	      });
458	      continue;
459	    }
460	
461	    if (compareResult.ahead_by === 0) {
462	      emit({ type: "feature_review_no_drift", feature_id: featureId });
463	      continue;
464	    }
465	
466	    emit({
467	      type: "feature_review_new_commits",
468	      feature_id: featureId,
469	      new_commits: compareResult.ahead_by,
470	    });
471	
472	    // ── Step 2: Extract files changed in new base commits ─────────────────────
473	    const newBaseFiles = (compareResult.files ?? []).map((f) => f.filename);
474	
475	    // ── Step 3: Get files changed by this feature's management repo PR ────────
476	    const featureFiles: string[] = [];
477	    const handoffPrUrl = statusYaml.handoff_pr_url;
478	    if (handoffPrUrl) {
479	      const prMatch = /\/pull\/(\d+)$/.exec(handoffPrUrl);
480	      if (prMatch) {
481	        const prNumber = prMatch[1];
482	        try {
483	          const files = curlJson([
484	            "-s",
485	            "-H", `Authorization: token ${githubToken}`,
486	            "-H", "Accept: application/vnd.github+json",
487	            `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}/files`,
488	          ]) as Array<{ filename: string }>;
489	          if (Array.isArray(files)) {
490	            featureFiles.push(...files.map((f) => f.filename));
491	          }
492	        } catch (e) {
493	          emit({
494	            type: "feature_review_pr_files_failed",
495	            feature_id: featureId,
496	            details: String(e),
497	          });
498	        }
499	      }
500	    }
501	
502	    // ── Step 4: File-overlap classification ───────────────────────────────────
503	    const { hasOverlap, overlappingFiles } = classifyFileOverlap(newBaseFiles, featureFiles);
504	
505	    if (!hasOverlap) {
506	      // Task-level: auto-rebase
507	      emit({
508	        type: "feature_review_task_level_drift",
509	        feature_id: featureId,
510	        new_commits: compareResult.ahead_by,
511	      });
512	      const rebaseResult = tryAutoRebase(opts, featureId);
