68	/**
69	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
70	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
71	 * instead of defaulting to whatever the Claude CLI ships with.
72	 */
73	function makeConflictResolver(
74	  model: string,
75	  maxTurns = 10,
76	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
77	  return (prompt, cwd, env) =>
78	    new Promise((resolve) => {
79	      const child = spawn(
80	        "claude",
81	        [
82	          "-p", prompt,
83	          "--model", model,
84	          "--max-turns", String(maxTurns),
85	          "--output-format", "stream-json",
86	          "--verbose",
87	          "--dangerously-skip-permissions",
88	        ],
89	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
90	      );
91	      child.stdout.pipe(process.stdout);
92	      child.stderr.pipe(process.stderr);
93	      child.on("close", (code) => resolve(code === 0));
94	      child.on("error", () => resolve(false));
95	    });
96	}
