158	/**
159	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
160	 * Commits and pushes to the task branch. Throws on error.
161	 */
162	function writeRagPreFlight(
163	  workspaceRoot: string,
164	  featureId: string,
165	  taskId: string,
166	  taskBranch: string,
167	  gitAuthorEmail: string,
168	  gitAuthorName: string,
169	  sshKeyPath: string | undefined,
170	  ragPreFlight: { query: string; injected: boolean; summary: string },
171	): void {
172	  const now = new Date().toISOString();
173	  const entry: TaskLogEntry = {
174	    action: "rag_pre_flight",
175	    by: gitAuthorEmail,
176	    at: now,
177	    rag_context_injected: ragPreFlight.injected,
178	    rag_summary: ragPreFlight.summary,
179	    rag_query: ragPreFlight.query,
180	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
181	  };
182	
183	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
184	  const relPath = taskYamlRelPath(featureId, taskId);
185	  const gitOpts = {
186	    cwd: workspaceRoot,
187	    encoding: "utf-8" as const,
188	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
189	    timeout: 30_000,
190	    stdio: "pipe" as const,
191	  };
192	
193	  // Anchor to the task branch tip before reading/writing — same pattern as
194	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
195	  // the task branch, but an explicit anchor makes this function self-contained.
196	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
197	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
198	
199	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
200	  task.log.push(entry);
201	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
202	
203	  execSync(`git add "${relPath}"`, gitOpts);
204	  execSync(
205	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
206	    gitOpts,
207	  );
208	  execSync(`git push origin "${taskBranch}"`, gitOpts);
209	}
