213	async function main(): Promise<number> {
214	  let agentYamlPath: string;
215	  let workflowLocalPath: string;
216	  let workspacesRoot: string;
217	  let gitAuthorEmail: string;
218	
219	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
220	  const bootstrapEmit = (event: Record<string, unknown>) => {
221	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
222	  };
223	
224	  try {
225	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
226	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
227	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
228	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
229	  } catch (e) {
230	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
231	    return 4;
232	  }
233	
234	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
235	
236	  const sshResolution = resolveSSHKey(process.env);
237	  const sshKeyPath = sshResolution.sshKeyPath;
238	
239	  // ── Create the runtime profile ────────────────────────────────────────────────
240	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
241	  // new infra is added without core changes.
242	  //   local-subprocess (default) — executor + in-process broker in one container
243	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
244	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
245	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
246	    runtimeProfile === "local-docker"
247	      ? createLocalDockerProfile({
248	          gitAuthorEmail,
249	          gitAuthorName,
250	          sshKeyPath,
251	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
252	        })
253	      : createLocalSubprocessProfile({
254	          gitAuthorEmail,
255	          gitAuthorName,
256	          sshKeyPath,
257	        });
258	
259	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
260	  const brokerPort = await ports.broker.start();
261	
262	  const emit = makeEmit(ports);
263	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
264	
265	  if (sshResolution.warned) {
266	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
267	  }
268	
269	  const bootstrapResult = await runBootstrap({
270	    agentYamlPath,
271	    workflowLocalPath,
272	    workflowUrl: process.env.WORKFLOW_URL,
273	    workspacesRoot,
274	    sshKeyPath,
275	  });
276	
277	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
278	
279	  const config = bootstrapResult.config!;
280	  const githubToken = process.env.GITHUB_TOKEN ?? "";
281	  if (!githubToken) emit({ type: "warn_no_github_token" });
282	
283	  let lastPrPollAt: number | null = null;
284	  // Local counter for local-docker mode — tracks how many executor containers are
285	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
286	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
287	  let dockerInFlight = 0;
288	  let cycleCount = 0;
289	  const stateInvariantCheckInterval = parseInt(
290	    process.env.STATE_INVARIANT_CHECK_INTERVAL ?? "5",
291	    10,
292	  );
293	  const featureReviewInterval = parseInt(
294	    process.env.FEATURE_REVIEW_INTERVAL ?? "20",
295	    10,
296	  );
