298	  async function buildAndSubmitExecutor(opts: {
299	    task: Task;
300	    featureId: string;
301	    workspaceId: string;
302	    taskRepoUrl: string;
303	    taskBranch: string;
304	    taskRepoRoot: string;
305	    implementationModel: string;
306	    briefingPath: string;
307	    resultPath: string;
308	    workspaceLocalPath: string;
309	  }) {
310	    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskRepoRoot,
311	            implementationModel, briefingPath, resultPath, workspaceLocalPath } = opts;
312	
313	    const nonce = randomUUID();
314	    const callbackUrl = ports.broker.getCallbackUrl() ?? "";
315	
316	    const execInput: ExecutorPortInput = {
317	      taskId: task.id,
318	      featureId,
319	      workspaceId,
320	      taskRepoUrl,
321	      taskRepoBranch: taskBranch,
322	      taskRepoPath: taskRepoRoot,
323	      briefingPath,
324	      resultPath,
325	      budgetTokens: config.budget.max_tokens_per_task,
326	      implementationModel,
327	      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
328	      githubToken,
329	      callbackUrl,
330	      nonce,
331	    };
332	
333	    const extraEnv: Record<string, string> = {
334	      WORKSPACE_ROOT: workspaceLocalPath,
335	      TASK_BRANCH: taskBranch,
336	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
337	      GIT_AUTHOR_NAME: gitAuthorName,
338	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
339	      MAX_TURNS: String(config.budget.max_iterations),
340	      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
341	      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
342	      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
343	        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
344	        : {}),
345	    };
346	
347	    const adapter =
348	      runtimeProfile === "local-docker"
349	        ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
350	            broker: ports.broker,
351	            extraEnv,
352	          })
353	        : new SubProcessAdapter({
354	            broker: ports.broker,
355	            extraEnv,
356	          });
357	
358	    return adapter.submit(execInput);
359	  }
