361	  async function runOneCycle(): Promise<CycleOutcome> {
362	    // In local-subprocess mode all repos share the same container filesystem.
363	    // If an executor is running, skip impl repo pulls — syncRepo would switch
364	    // the shared working tree to the base branch and hard-reset it, destroying
365	    // any uncommitted work the executor has in flight.
366	    const execInFlight =
367	      runtimeProfile === "local-subprocess"
368	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
369	        : false;
370	
371	    const pullResults = pullWorkspaces({
372	      watchUrls: config.watches,
373	      sshKeyPath,
374	      workspacesRoot,
375	      workflowUrl: process.env.WORKFLOW_URL,
376	      workflowLocalPath,
377	      skipImplRepoPull: execInFlight,
378	      emit,
379	    });
380	
381	    const haltedUrls = new Set(
382	      pullResults
383	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
384	        .map((r) => r.url),
385	    );
386	
387	    // ── Feature Branch Lifecycle Manager — run every poll cycle ──────────────
388	    // Ensures feature branches exist and are synced before any claim or dispatch.
389	    // Idempotent: if the branch already exists this is a cheap ls-remote + no-op.
390	    // Running per-cycle means a branch deleted mid-session (e.g. workspace PR
391	    // merged + deleted) is recreated before the next claim attempt, preventing
392	    // 422 "invalid base" errors on workspace PR creation.
393	    const failedFeatureBranchMap = new Map<string, Set<string>>();
394	    for (const watchUrl of config.watches) {
395	      if (haltedUrls.has(watchUrl)) continue;
396	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
397	      if (!existsSync(workspaceLocalPath)) continue;
398	      try {
399	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
400	        const failed = runFeatureBranchLifecycle({
401	          workspaceRoot: workspaceLocalPath,
402	          baseBranch: mgmtCoords.baseBranch,
403	          gitAuthorEmail,
404	          gitAuthorName,
405	          sshKeyPath,
406	          githubToken: githubToken || undefined,
407	          repoOwner: mgmtCoords.owner,
408	          repoName: mgmtCoords.repo,
409	          emit,
410	        });
411	        if (failed.size > 0) {
412	          failedFeatureBranchMap.set(workspaceLocalPath, failed);
413	          emit({ type: "feature_branch_lifecycle_blocked", workspace: watchUrl, failed_features: [...failed] });
414	        }
415	      } catch (e) {
416	        emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
417	      }
418	    }
419	
420	    let outcome: CycleOutcome = "idle";
421	    const pulledWorkspaceRoots: string[] = [];
422	
423	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
424	    // In local-subprocess mode all repos share the same container filesystem.
425	    // Two concurrent subprocesses can race on git checkouts in the same repo.
426	    // Wrap the dispatch loop in a labeled block so we can break out of it
427	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
428	    dispatchBlock: {
429	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
430	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
431	
432	      if (runtimeProfile === "local-subprocess") {
433	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
434	        if (inFlight >= maxConcurrent) {
435	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
436	          break dispatchBlock;
437	        }
438	      } else if (runtimeProfile === "local-docker") {
439	        if (dockerInFlight >= maxConcurrent) {
440	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
441	          break dispatchBlock;
442	        }
443	      }
444	
445	    outerLoop:
446	    for (const watchUrl of config.watches) {
447	      if (haltedUrls.has(watchUrl)) continue;
448	
449	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
450	      pulledWorkspaceRoots.push(workspaceLocalPath);
451	
452	      if (!existsSync(workspaceLocalPath)) {
453	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
454	        continue;
455	      }
456	
457	      let eligibleTasks;
458	      try {
459	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
460	      } catch (e) {
461	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
462	        continue;
463	      }
464	
465	      if (eligibleTasks.length === 0) {
466	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
467	        continue;
468	      }
469	
470	      for (const { task, featureId } of eligibleTasks) {
471	        if (failedFeatureBranchMap.get(workspaceLocalPath)?.has(featureId)) {
472	          emit({ type: "task_skipped_feature_branch_failed", task_id: task.id, feature_id: featureId });
473	          continue;
474	        }
475	
476	        const claimResult = await claimTask({
477	          workspaceRoot: workspaceLocalPath,
478	          taskId: task.id,
479	          featureId,
480	          gitAuthorEmail,
481	          gitAuthorName,
482	          sshKeyPath,
483	          jitterMaxSeconds: config.jitter_max_seconds,
484	          baseBranch: featureBranchName(featureId),
485	        });
486	
487	        const taskBranch = taskBranchName(featureId, task.id);
488	
489	        if (!claimResult.won) {
490	          if (claimResult.reason !== "branch_blocked_recovery") {
491	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
492	            continue;
493	          }
494	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
495	        } else {
496	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
497	        }
498	
499	        // ── Open management-repo PR ───────────────────────────────────────────
500	        if (githubToken) {
501	          try {
502	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
503	            await openWorkspacePr({
504	              workspaceRoot: workspaceLocalPath,
505	              featureId,
506	              taskId: task.id,
507	              branch: taskBranch,
508	              // Task PRs target the feature branch so all task changes collect
509	              // there before the Handoff Trigger merges to the base branch (T8).
510	              baseBranch: featureBranchName(featureId),
511	              githubToken,
512	              repoOwner: mgmtCoords.owner,
513	              repoName: mgmtCoords.repo,
514	              gitAuthorEmail,
515	              gitAuthorName,
516	              sshKeyPath,
517	            });
518	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
519	          } catch (e) {
520	            const stderr = (e as { stderr?: Buffer | string }).stderr;
521	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
522	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
523	          }
524	        }
525	
526	        // ── Resolve model + task repo ────────────────────────────────────────
527	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
528	          resolveTaskContext(workspaceLocalPath, featureId, task);
529	
530	        // ── RAG pre-flight ───────────────────────────────────────────────────
531	        const mcpRagUrl = process.env.MCP_RAG_URL;
532	        const workspaceYaml = parseYaml(
533	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
534	        ) as { workspace_id: string };
535	        const ragQuery = `${task.title} ${featureId}`;
536	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
537	
538	        try {
539	          writeRagPreFlight(
540	            workspaceLocalPath,
541	            featureId,
542	            task.id,
543	            taskBranch,
544	            gitAuthorEmail,
545	            gitAuthorName,
546	            sshKeyPath,
547	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
548	          );
549	        } catch (e) {
550	          const details = String(e);
551	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
552	          mutateTaskYaml({
553	            workspaceRoot: workspaceLocalPath,
554	            featureId,
555	            taskId: task.id,
556	            taskBranch,
557	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
558	            gitAuthorEmail,
559	            gitAuthorName,
560	            sshKeyPath,
561	          });
562	          continue;
563	        }
564	
565	        // ── Generate briefing ────────────────────────────────────────────────
566	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
567	        const baseContext = generateBriefing({
568	          taskId: task.id,
569	          featureId,
570	          taskTitle: task.title,
571	          taskBranch,
572	          taskRepo: task.repo,
573	          taskRepoRoot,
574	          workspaceRoot: workspaceLocalPath,
575	          gitAuthorEmail,
576	          gitAuthorName,
577	          implementationModel,
578	          resultPath,
579	        });
580	        const briefingContent = ragPreFlight.block
581	          ? `${baseContext}\n\n${ragPreFlight.block}`
582	          : baseContext;
583	
584	        // ── Write briefing via BriefingTransportPort ─────────────────────────
585	        // Use taskId as the briefing handle so the file path matches the
586	        // existing briefing-{taskId}/briefing.md convention.
587	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
588	
589	        // ── Submit executor (async — T6) ─────────────────────────────────────
590	        const execHandle = await buildAndSubmitExecutor({
591	          task, featureId, workspaceId: workspaceYaml.workspace_id,
592	          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
593	          briefingPath, resultPath, workspaceLocalPath,
594	        });
595	
596	        // Persist handle to task YAML for broker crash-recovery reconciliation.
597	        try {
598	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
599	        } catch (e) {
600	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
601	        }
602	
603	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
604	        if (runtimeProfile === "local-docker") dockerInFlight++;
605	        outcome = "ran_task";
606	        break outerLoop;
607	      }
608	    }
609	
610	    // ── Fix-agent dispatch ────────────────────────────────────────────────────
611	    if (outcome !== "ran_task") {
612	      fixLoop:
613	      for (const watchUrl of config.watches) {
614	        if (haltedUrls.has(watchUrl)) continue;
615	
616	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
617	        if (!existsSync(workspaceLocalPath)) continue;
618	
619	        let fixableTasks;
620	        try {
621	          fixableTasks = findFixableTasks(config, workspaceLocalPath);
622	        } catch (e) {
623	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
624	          continue;
625	        }
626	
627	        for (const { task, featureId } of fixableTasks) {
628	          const taskBranch = taskBranchName(featureId, task.id);
629	          const claimResult = await claimFixTask({
630	            workspaceRoot: workspaceLocalPath,
631	            taskId: task.id,
632	            featureId,
633	            gitAuthorEmail,
634	            gitAuthorName,
635	            jitterMaxSeconds: config.jitter_max_seconds,
636	          });
637	
638	          if (!claimResult.won) {
639	            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
640	            continue;
641	          }
642	
643	          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
644	
645	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
646	          const fixWsYaml = parseYaml(
647	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
648	          ) as { workspace_id: string };
649	
650	          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
651	          const prUrl = extractPrUrlFromTask(task);
652	          const fixContext = generateFixBriefing({
653	            taskId: task.id,
654	            featureId,
655	            taskTitle: task.title,
656	            taskBranch,
657	            taskRepo: task.repo,
658	            taskRepoRoot,
659	            workspaceRoot: workspaceLocalPath,
660	            prUrl: prUrl ?? "",
661	            gitAuthorEmail,
662	            gitAuthorName,
663	            implementationModel,
664	            resultPath,
665	          });
666	
667	          emit({ type: "fix_briefing_generated", task_id: task.id, feature_id: featureId, pr_url: prUrl });
668	          const fixBriefingPath = await ports.briefing.put(task.id, fixContext);
669	          const fixHandle = await buildAndSubmitExecutor({
670	            task, featureId, workspaceId: fixWsYaml.workspace_id,
671	            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
672	            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
673	          });
674	          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
675	          if (runtimeProfile === "local-docker") dockerInFlight++;
676	          outcome = "ran_task";
677	          break fixLoop;
678	        }
679	      }
680	    }
681	
682	    // ── Reviewer dispatch ─────────────────────────────────────────────────────
683	    if (outcome !== "ran_task") {
684	      reviewerLoop:
685	      for (const watchUrl of config.watches) {
686	        if (haltedUrls.has(watchUrl)) continue;
687	
688	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
689	        if (!existsSync(workspaceLocalPath)) continue;
690	
691	        let reviewableTasks;
692	        try {
693	          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
694	        } catch (e) {
695	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
696	          continue;
697	        }
698	
699	        for (const { task, featureId } of reviewableTasks) {
700	          const taskBranch = taskBranchName(featureId, task.id);
701	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
702	          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
703	          const revWsYaml = parseYaml(
704	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
705	          ) as { workspace_id: string };
706	          let reviewModelOverrides = {};
707	          try {
708	            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
709	            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
710	          } catch { /* non-fatal */ }
711	          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);
712	
713	          const dispatchResult = await dispatchReviewer({
714	            workspaceRoot: workspaceLocalPath,
715	            featureId,
716	            taskId: task.id,
717	            taskBranch,
718	            implRepoRoot: taskRepoRoot,
719	            implRepoUrl: taskRepoUrl,
720	            gitAuthorEmail,
721	            gitAuthorName,
722	            workflowLocalPath,
723	            maxTurns: config.budget.max_iterations,
724	            maxTokens: config.budget.max_tokens_per_task,
725	            logSinkEnabled: config.log_sink.enabled,
726	            reviewerModel,
727	            workspaceId: revWsYaml.workspace_id,
728	            githubToken,
729	            broker: ports.broker,
730	            callbackUrl: ports.broker.getCallbackUrl() ?? "",
731	            emit,
732	          });
733	
734	          if (dispatchResult === "dispatched") {
735	            if (runtimeProfile === "local-docker") dockerInFlight++;
736	            outcome = "ran_task";
