738	          }
739	        }
740	      }
741	    }
742	    } // end dispatchBlock
743	
744	    // ── In-review PR poll ─────────────────────────────────────────────────────
745	    // In local-subprocess mode the executor subprocess shares the same container
746	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
747	    // repo — a second rebase operation fails with "rebase-merge directory already
748	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
749	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
750	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
751	    const skipPrPoll =
752	      runtimeProfile === "local-subprocess" &&
753	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
754	    if (githubToken && !skipPrPoll) {
755	      const prPollIntervalMs =
756	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
757	      const now = Date.now();
758	
759	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
760	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
761	        try {
762	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
763	            workspaceRoots: pulledWorkspaceRoots,
764	            githubToken,
765	            emit,
766	          });
767	
768	          for (const wsRoot of pulledWorkspaceRoots) {
769	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
770	            if (wsResults.some((r) => r.mergeable === false)) {
771	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
772	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
773	              await handleMergeConflicts({
774	                prResults: wsResults,
775	                workspaceRoot: wsRoot,
776	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
777	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
778	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
779	                gitAuthorEmail,
780	                gitAuthorName,
781	                sshKeyPath,
782	                emit,
783	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
784	              });
785	            }
786	          }
787	
788	          for (const wsRoot of pulledWorkspaceRoots) {
789	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
790	            if (wsResults.some((r) => r.merged === true)) {
791	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
792	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
793	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
794	              await handleMergedPrs({
795	                prResults: wsResults,
796	                workspaceRoot: wsRoot,
797	                mgmtRepoOwner: mgmtCoords.owner,
798	                mgmtRepoName: mgmtCoords.repo,
799	                mgmtBaseBranch: mgmtCoords.baseBranch,
800	                githubToken,
801	                gitAuthorEmail,
802	                gitAuthorName,
803	                sshKeyPath,
804	                emit,
805	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
806	              });
807	            }
808	          }
809	
810	          for (const wsRoot of pulledWorkspaceRoots) {
811	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
812	            if (wsRecoveries.length > 0) {
813	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
814	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
815	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
816	              await handleWorkspacePrRecoveries({
817	                recoveries: wsRecoveries,
818	                mgmtRepoOwner: mgmtCoords.owner,
819	                mgmtRepoName: mgmtCoords.repo,
820	                mgmtBaseBranch: mgmtCoords.baseBranch,
821	                githubToken,
822	                gitAuthorEmail,
823	                gitAuthorName,
824	                sshKeyPath,
825	                emit,
826	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
827	              });
828	            }
829	          }
830	        } catch (e) {
831	          emit({ type: "in_review_poll_error", details: String(e) });
832	        }
833	      }
834	    }
835	
836	    // ── Feature Done Watcher ──────────────────────────────────────────────────
837	    // Transitions feature_status from in_handoff to done when all PRs are merged.
838	    if (githubToken) {
839	      for (const wsRoot of pulledWorkspaceRoots) {
840	        try {
841	          await handleFeatureDone({
842	            workspaceRoot: wsRoot,
843	            githubToken,
844	            gitAuthorEmail,
845	            gitAuthorName,
846	            sshKeyPath,
847	            emit,
848	          });
849	        } catch (e) {
850	          emit({ type: "feature_done_watcher_error", workspace: wsRoot, details: String(e) });
851	        }
852	      }
853	    }
854	
855	    // ── Feature Reviewer Daemon (every FEATURE_REVIEW_INTERVAL cycles) ──────────
856	    // Detects base-branch drift for in_handoff features; auto-rebases on task-level
857	    // drift; escalates to human on feature-level drift or rebase conflict.
858	    cycleCount++;
859	    if (cycleCount % featureReviewInterval === 0) {
860	      for (const wsRoot of pulledWorkspaceRoots) {
861	        try {
862	          const mgmtCoords = parseManagementRepoCoords(wsRoot);
863	          await runFeatureReviewCycle({
864	            workspaceRoot: wsRoot,
865	            baseBranch: mgmtCoords.baseBranch,
866	            mgmtRepoOwner: mgmtCoords.owner,
867	            mgmtRepoName: mgmtCoords.repo,
868	            githubToken,
869	            reviewerGithubToken: process.env.REVIEWER_GITHUB_TOKEN,
870	            gitAuthorEmail,
871	            gitAuthorName,
872	            sshKeyPath,
873	            anthropicApiKey: process.env.ANTHROPIC_API_KEY,
874	            slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
875	            emit,
876	          });
877	        } catch (e) {
878	          emit({ type: "feature_review_cycle_error", workspace: wsRoot, details: String(e) });
879	        }
880	      }
881	    }
882	
883	    // ── State invariant checker (every N cycles) ──────────────────────────────
884	    if (cycleCount % stateInvariantCheckInterval === 0) {
885	      for (const wsRoot of pulledWorkspaceRoots) {
886	        try {
887	          await runStateInvariantCheck({
888	            workspaceRoot: wsRoot,
889	            githubToken,
890	            gitAuthorEmail,
891	            gitAuthorName,
892	            sshKeyPath,
893	            emit,
894	          });
895	        } catch (e) {
896	          emit({ type: "state_invariant_check_error", workspace: wsRoot, details: String(e) });
897	        }
898	      }
899	    }
900	
901	    // ── Shared reap loop ──────────────────────────────────────────────────────
902	    // Drain completions posted by in-flight executors this cycle (and any
903	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
904	    try {
905	      const reapResult = await runReapLoop({
906	        broker: ports.broker,
907	        workspaceRoots: pulledWorkspaceRoots,
908	        gitAuthorEmail,
909	        gitAuthorName,
910	        sshKeyPath,
911	        githubToken,
912	        emit,
913	      });
914	      if (reapResult.dispatched > 0) {
915	        if (runtimeProfile === "local-docker") {
916	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
917	        }
918	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
919	        if (outcome === "idle") outcome = "ran_task";
920	      }
921	    } catch (e) {
922	      emit({ type: "reap_loop_error", details: String(e) });
923	    }
924	
925	    return outcome;
926	  }
927	
928	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
929	  return 0;
930	}
931	
932	main()
933	  .then((code) => process.exit(code))
934	  .catch((e) => {
935	    try {
936	      console.log(JSON.stringify({
937	        type: "fatal_error",
938	        details: (e as Error).message ?? String(e),
939	        at: new Date().toISOString(),
940	      }));
941	    } catch { /* last resort */ }
942	    process.exit(4);
943	  });
